{"implementation": "def solve(case):
    text = case['text']
    passes = case['passes']
    max_rounds = case['max_rounds']
    applications = []
    for _ in range(max_rounds):
        changed = False
        for pass_ in passes:
            old = pass_['old']
            new = pass_['new']
            idx = text.find(old)
            if idx != -1:
                text = text[:idx] + new + text[idx+len(old):]
                applications.append(pass_['name'])
                changed = True
        if not changed:
            return {'applications': applications, 'fixed_point': True, 'text': text}
    return {'applications': applications, 'fixed_point': False, 'text': text}
"}
